package repository
import("context";"fmt";"github.com/imamsyafii-dev/ledgerflow/backend/internal/model";"github.com/jackc/pgx/v5/pgxpool")
type RefundRepository struct{db *pgxpool.Pool};func NewRefundRepository(db *pgxpool.Pool)*RefundRepository{return &RefundRepository{db}}
func(r *RefundRepository)Create(c context.Context,o,p,u,reason string)(model.RefundRequest,error){const q=`INSERT INTO refund_requests(organization_id,payment_id,requested_by,reason) SELECT $1,id,$3,$4 FROM payments WHERE id=$2 AND organization_id=$1 AND status='SUCCEEDED' RETURNING id::text,organization_id::text,payment_id::text,requested_by::text,reason,status,created_at`;var x model.RefundRequest;err:=r.db.QueryRow(c,q,o,p,u,reason).Scan(&x.ID,&x.OrganizationID,&x.PaymentID,&x.RequestedBy,&x.Reason,&x.Status,&x.CreatedAt);return x,err}
func(r *RefundRepository)List(c context.Context,o string)([]model.RefundRequest,error){const q=`SELECT r.id::text,r.organization_id::text,r.payment_id::text,i.number,c.name,p.amount,p.currency,r.requested_by::text,u.name,r.reason,r.status,r.decided_by::text,r.decision_note,r.decided_at,r.created_at FROM refund_requests r JOIN payments p ON p.id=r.payment_id JOIN invoices i ON i.id=p.invoice_id JOIN customers c ON c.id=i.customer_id JOIN users u ON u.id=r.requested_by WHERE r.organization_id=$1 ORDER BY r.created_at DESC`;rows,e:=r.db.Query(c,q,o);if e!=nil{return nil,e};defer rows.Close();out:=[]model.RefundRequest{};for rows.Next(){var x model.RefundRequest;if e=rows.Scan(&x.ID,&x.OrganizationID,&x.PaymentID,&x.InvoiceNumber,&x.CustomerName,&x.Amount,&x.Currency,&x.RequestedBy,&x.RequestedByName,&x.Reason,&x.Status,&x.DecidedBy,&x.DecisionNote,&x.DecidedAt,&x.CreatedAt);e!=nil{return nil,fmt.Errorf("scan refund: %w",e)};out=append(out,x)};return out,rows.Err()}
func(r *RefundRepository)Decide(c context.Context,o,id,actor string,s model.RefundStatus,note string)(model.RefundRequest,error){const q=`UPDATE refund_requests SET status=$4,decided_by=$3,decision_note=$5,decided_at=NOW(),updated_at=NOW() WHERE id=$2 AND organization_id=$1 AND status='PENDING' AND requested_by<>$3 RETURNING id::text,organization_id::text,payment_id::text,requested_by::text,reason,status,decided_by::text,decision_note,decided_at,created_at`;var x model.RefundRequest;e:=r.db.QueryRow(c,q,o,id,actor,s,note).Scan(&x.ID,&x.OrganizationID,&x.PaymentID,&x.RequestedBy,&x.Reason,&x.Status,&x.DecidedBy,&x.DecisionNote,&x.DecidedAt,&x.CreatedAt);return x,e}
